import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './EmptyState.module.css'

export interface EmptyStateProps extends Omit<ComponentProps<'div'>, 'title'> {
  /** An icon (`<Icon name="search" />`) or a small illustration. Decorative. */
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  /** What to do next: usually one Button, at most two. */
  action?: ReactNode
  /** `sm` for a panel or a table body; `md` for a whole page or section. */
  size?: 'sm' | 'md'
  /** The title's heading level, so it fits the page outline it lands in. */
  headingLevel?: 2 | 3 | 4 | 5 | 6
}

export function EmptyState({
  icon,
  title,
  description,
  action,
  size = 'md',
  headingLevel = 2,
  className,
  ...props
}: EmptyStateProps) {
  const Heading = `h${headingLevel}` as const
  return (
    <div className={cn(styles.empty, styles[size], className)} {...props}>
      {icon && (
        <span className={styles.icon} aria-hidden="true">
          {icon}
        </span>
      )}
      <Heading className={styles.title}>{title}</Heading>
      {description && <p className={styles.description}>{description}</p>}
      {action && <div className={styles.action}>{action}</div>}
    </div>
  )
}

.empty {
  --empty-icon: var(--space-12);
  display: flex;
  flex-direction: column;
  align-items: center;
  box-sizing: border-box;
  padding: calc(var(--space-section) * 2) var(--space-container);
  font-family: var(--font-sans);
  text-align: center;
  color: var(--color-text);
}

.sm {
  --empty-icon: var(--space-10);
  padding: calc(var(--space-group) * 2) var(--space-group);
}

/* A soft disc behind the icon: it gives an empty area a centre of gravity
   without an illustration. */
.icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--empty-icon);
  block-size: var(--empty-icon);
  /* md follows Atlassian's empty state: 24px under the image, 16px under
     the heading, 24px above the buttons. sm keeps the 16 and 24 and is a
     step tighter only under the image. */
  margin-block-end: var(--space-container);
  border-radius: var(--radius-pill);
  /* Error State and Success State set these to their own tone. */
  background: var(--empty-icon-bg, var(--color-background-neutral));
  color: var(--empty-icon-fg, var(--color-text-subtlest));
  font-size: calc(var(--empty-icon) / 2);
}

.sm .icon {
  margin-block-end: var(--space-group);
}

/* Atlassian's widths: 464px (wide) at md, 304px (narrow) at sm. */
.title,
.description {
  max-inline-size: 29rem;
}
.sm .title,
.sm .description {
  max-inline-size: 19rem;
}

.title {
  margin: 0;
  font-size: var(--text-heading-md);
  line-height: var(--leading-heading-md);
  font-family: var(--font-heading);
  font-weight: 600;
}
.sm .title {
  font-size: var(--text-heading-sm);
  line-height: var(--leading-heading-sm);
}

.description {
  /* Spacing on padding, not margin: a host page's element reset
     (`p, div { margin: 0 }` at class specificity) can zero a margin and put
     the button flush against the text. Padding survives it. */
  margin: 0;
  padding-block-start: var(--space-group);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--color-text-subtlest);
}

.action {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  /* 8px between buttons, as Figma. */
  gap: var(--space-inline);
  padding-block-start: var(--space-container);
}
